-- "Anda" to "kamu" in the shipped copy. Data-only, respects admin edits: a column is rewritten only while it still equals the old default; the seed upserts the new text from the catalog.
UPDATE "email_templates" SET "body" = '<p>Hai {{name}},</p><p>{{inviterName}} mengundang kamu sebagai staf {{appName}} dengan peran <strong>{{roleName}}</strong>.</p><p><a class="btn" href="{{inviteUrl}}">Terima undangan</a></p><p>Undangan berlaku sampai {{expiresAt}}.</p>', "updated_at" = now() WHERE "key" = 'staff_invitation' AND "body" = '<p>Hai {{name}},</p><p>{{inviterName}} mengundang Anda sebagai staf {{appName}} dengan peran <strong>{{roleName}}</strong>.</p><p><a class="btn" href="{{inviteUrl}}">Terima undangan</a></p><p>Undangan berlaku sampai {{expiresAt}}.</p>';--> statement-breakpoint
UPDATE "email_templates" SET "subject" = 'Paket {{planName}} kamu berakhir {{daysLeft}} hari lagi', "updated_at" = now() WHERE "key" = 'renewal_reminder' AND "subject" = 'Paket {{planName}} Anda berakhir {{daysLeft}} hari lagi';--> statement-breakpoint
UPDATE "email_templates" SET "body" = '<p>Halo {{name}},</p><p>Paket <strong>{{planName}}</strong> untuk {{workspaceName}} berakhir pada {{periodEnd}}. Perpanjang sekarang ({{amount}}) agar postingan terjadwal tetap jalan. Membayar lebih awal tidak mengurangi sisa waktu kamu.</p><p><a class="btn" href="{{billingUrl}}">Perpanjang paket</a></p>', "updated_at" = now() WHERE "key" = 'renewal_reminder' AND "body" = '<p>Halo {{name}},</p><p>Paket <strong>{{planName}}</strong> untuk {{workspaceName}} berakhir pada {{periodEnd}}. Perpanjang sekarang ({{amount}}) agar postingan terjadwal tetap jalan. Membayar lebih awal tidak mengurangi sisa waktu Anda.</p><p><a class="btn" href="{{billingUrl}}">Perpanjang paket</a></p>';--> statement-breakpoint
UPDATE "email_templates" SET "body" = '<p>Halo {{name}},</p><p>Pembayaran {{amount}} untuk paket <strong>{{planName}}</strong> ({{workspaceName}}) belum berhasil. Selesaikan sebelum {{graceEndsAt}} agar paket kamu tidak turun ke Gratis.</p><p><a class="btn" href="{{billingUrl}}">Bayar sekarang</a></p>', "updated_at" = now() WHERE "key" = 'payment_failed' AND "body" = '<p>Halo {{name}},</p><p>Pembayaran {{amount}} untuk paket <strong>{{planName}}</strong> ({{workspaceName}}) belum berhasil. Selesaikan sebelum {{graceEndsAt}} agar paket Anda tidak turun ke Gratis.</p><p><a class="btn" href="{{billingUrl}}">Bayar sekarang</a></p>';--> statement-breakpoint
UPDATE "email_templates" SET "body" = '<p>Halo {{name}},</p><p>Akun {{workspaceName}} sekarang memakai paket <strong>{{planName}}</strong>. Data kamu tidak dihapus. {{#disabledAccounts}}Akun sosial yang dinonaktifkan sementara: {{disabledAccounts}}. {{/disabledAccounts}}{{#pausedRules}}Aturan Balas Otomatis yang dijeda: {{pausedRules}}. {{/pausedRules}}Semua aktif lagi saat kamu upgrade.</p><p><a class="btn" href="{{accountSelectionUrl}}">Pilih akun yang tetap aktif</a></p>', "updated_at" = now() WHERE "key" = 'subscription_downgraded' AND "body" = '<p>Halo {{name}},</p><p>Akun {{workspaceName}} sekarang memakai paket <strong>{{planName}}</strong>. Data Anda tidak dihapus. {{#disabledAccounts}}Akun sosial yang dinonaktifkan sementara: {{disabledAccounts}}. {{/disabledAccounts}}{{#pausedRules}}Aturan Balas Otomatis yang dijeda: {{pausedRules}}. {{/pausedRules}}Semua aktif lagi saat Anda upgrade.</p><p><a class="btn" href="{{accountSelectionUrl}}">Pilih akun yang tetap aktif</a></p>';--> statement-breakpoint
UPDATE "notification_templates" SET "body" = 'Pilih akun sosial yang tetap aktif. Data kamu tidak dihapus.', "updated_at" = now() WHERE "key" = 'subscription_downgraded' AND "body" = 'Pilih akun sosial yang tetap aktif. Data Anda tidak dihapus.';--> statement-breakpoint
UPDATE "app_settings" SET "value" = 'Publikasi sedang dijeda sementara karena gangguan dari platform. Postingan kamu tetap terjadwal.', "updated_at" = now() WHERE "key" = 'channels.publishing.pausedMessage' AND "value" = 'Publikasi sedang dijeda sementara karena gangguan dari platform. Postingan Anda tetap terjadwal.';
